<?php
/**
 * Sales Reporter — SETUP CHECK  (api/setup_check.php)
 *
 * Open in a browser:  https://<your-site>/<folder>/api/setup_check.php
 * Shows, in plain words, whether config.php can reach the database and
 * which tables are missing. "Create missing tables" adds only tables that
 * do not exist yet (CREATE TABLE IF NOT EXISTS) — it never deletes or
 * changes existing tables or data. Passwords are never displayed.
 *
 * DELETE THIS FILE once the app works.
 */
header('Content-Type: text/html; charset=utf-8');
header('X-Robots-Tag: noindex');
ini_set('display_errors', '0');

$EXPECTED = json_decode('["users", "advance_approval_log", "advance_request_approvals", "advance_request_attachments", "advance_requests", "app_settings", "customers", "expense_attachments", "expense_bills", "expenses", "lead_assignment_rules", "lead_contact_activity", "password_resets", "plans", "rate_master", "sales_report_rows", "sales_reports", "sessions", "tally_ledger_entries", "tasks", "visits"]', true);
$INSTALL  = json_decode(base64_decode(''), true);

function h($s) { return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8'); }
$rows = []; $fix = [];
$ok = function ($label, $good, $detail = '') use (&$rows) { $rows[] = [$label, $good, $detail]; };

$cfg = __DIR__ . '/../config.php';
if (!is_file($cfg)) {
    $ok('config.php in this folder', false, 'Missing. Upload config.php next to index.php (not inside api/).');
} else {
    $ok('config.php in this folder', true);
    try { require_once $cfg; } catch (Throwable $e) { $ok('config.php loads', false, 'PHP error in config.php: ' . $e->getMessage()); }
    $name = $DB_NAME ?? ''; $user = $DB_USER ?? ''; $host = $DB_HOST ?? '';
    $ok('Database name in config.php', $name !== '', $name ? h($name) : 'DB_NAME is empty');
    $placeholder = stripos($user . ($DB_PASS ?? ''), 'PUT_NEW_') !== false;
    $ok('Database user/password filled in', !$placeholder && $user !== '', $placeholder ? 'config.php still has PUT_NEW_DB_USERNAME_HERE / PUT_NEW_DB_PASSWORD_HERE — replace them with the user and password of ' . h($name) . ' (hPanel → Databases).' : 'user: ' . h($user));
    $pdo = null;
    if (!$placeholder) {
        try {
            $pdo = new PDO("mysql:host={$host};dbname={$name};charset=utf8mb4", $user, $DB_PASS ?? '', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_TIMEOUT => 8]);
            $ok('Connect to database', true, h($host) . ' / ' . h($name));
        } catch (PDOException $e) {
            $m = $e->getMessage(); $why = 'Could not connect.';
            if (strpos($m, '1045') !== false) $why = 'Access denied: the database USER or PASSWORD in config.php is wrong for ' . h($name) . '. Check them in hPanel → Databases (you can change the password there), then save config.php.';
            elseif (strpos($m, '1044') !== false) $why = 'This user is not allowed to use database ' . h($name) . '. In hPanel → Databases, use the user that belongs to this database.';
            elseif (strpos($m, '1049') !== false) $why = 'Database ' . h($name) . ' does not exist. Check DB_NAME in config.php (exact spelling, including u924350731_ prefix).';
            elseif (preg_match('/2002|2005|getaddrinfo/i', $m)) $why = 'Database host "' . h($host) . '" not reachable. On Hostinger DB_HOST should be localhost.';
            $ok('Connect to database', false, $why);
        }
    }
    if ($pdo) {
        $have = $pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);
        $missing = array_values(array_diff($EXPECTED, $have));
        if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST' && ($_POST['action'] ?? '') === 'install') {
            $pdo->exec('SET FOREIGN_KEY_CHECKS = 0');
            foreach ($INSTALL as $sql) { try { $pdo->exec($sql); } catch (PDOException $e) { $fix[] = $e->getMessage(); } }
            $pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
            $have = $pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);
            $missing = array_values(array_diff($EXPECTED, $have));
        }
        $ok('All ' . count($EXPECTED) . ' tables present', !$missing, $missing ? 'Missing: ' . h(implode(', ', $missing)) : count($have) . ' tables found');
        if (in_array('users', $have, true)) {
            $n = (int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
            $ok('User accounts', $n > 0, $n > 0 ? $n . ' user(s). Log in with one of them.' : 'No users yet. Open the app → "Create an account" → choose General Manager or CEO.');
        }
    }
}
$allGood = !array_filter($rows, fn($r) => !$r[1]);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sales Reporter — setup check</title>
<style>body{font:15px/1.5 system-ui,sans-serif;background:#E6EBF3;color:#1A2433;margin:0;padding:24px 16px}main{max-width:720px;margin:auto;background:#fff;border-radius:18px;padding:22px;box-shadow:0 10px 30px rgba(15,45,92,.15)}h1{font-size:20px;margin:0 0 4px}p.s{color:#687D99;margin:0 0 16px}.r{display:flex;gap:12px;padding:11px 0;border-bottom:1px solid #E2E7EF}.r:last-child{border:0}.i{font-weight:700;width:22px}.g{color:#2F7A4F}.b{color:#B85450}.d{color:#687D99;font-size:13px}button{background:#0F2D5C;color:#fff;border:0;border-radius:10px;padding:12px 18px;font:600 14px system-ui;cursor:pointer;margin-top:14px}.ok{background:#DFF1E6;color:#2F7A4F;padding:12px;border-radius:10px;margin-top:14px}.err{background:#F4DEDD;color:#B85450;padding:12px;border-radius:10px;margin-top:14px;font-size:13px}</style></head><body><main>
<h1>Sales Reporter — setup check</h1><p class="s">Fix the first red line, refresh this page, repeat until everything is green.</p>
<?php foreach ($rows as [$l, $g, $d]): ?><div class="r"><span class="i <?= $g ? 'g' : 'b' ?>"><?= $g ? '✓' : '✗' ?></span><div><div><?= h($l) ?></div><?php if ($d): ?><div class="d"><?= $d ?></div><?php endif; ?></div></div><?php endforeach; ?>
<?php if (!empty($missing)): ?><form method="post"><input type="hidden" name="action" value="install"><button type="submit">Create missing tables</button></form><?php endif; ?>
<?php if ($fix): ?><div class="err">Some tables could not be created:<br><?= h(implode(' | ', $fix)) ?></div><?php endif; ?>
<?php if ($allGood): ?><div class="ok">Everything is ready. Open the app and log in. Then delete this file (api/setup_check.php).</div><?php endif; ?>
</main></body></html>
